import{_ as a,a0 as p,w as l,s as d,I as i,x as s,a1 as e,A as o,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 中不使用功能鍵在 TTY 之間切換 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中不使用功能鍵在 TTY 之間切換 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中不使用功能鍵在 TTY 之間切換 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中不使用功能鍵在 TTY 之間切換 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180822 How To Switch Between TTYs Without Using Function Keys In Linux","title":"如何在 Linux 中不使用功能鍵在 TTY 之間切換","tag":"201809","desc":""},"relativePath":"201809/20180822 How To Switch Between TTYs Without Using Function Keys In Linux.md","filePath":"[post].md"}'),r={name:"201809/20180822 How To Switch Between TTYs Without Using Function Keys In Linux.md"};function h(g,t,T,k,c,b){const n=p("Link");return l(),d("div",null,[t[24]||(t[24]=i("h1",{id:"如何在-linux-中不使用功能鍵在-tty-之間切換",tabindex:"-1"},[s("如何在 Linux 中不使用功能鍵在 TTY 之間切換 "),i("a",{class:"header-anchor",href:"#如何在-linux-中不使用功能鍵在-tty-之間切換","aria-label":"Permalink to “如何在 Linux 中不使用功能鍵在 TTY 之間切換”"},"​")],-1)),t[25]||(t[25]=i("p",null,[i("img",{src:"https://www.ostechnix.com/wp-content/uploads/2018/08/Switch-Between-TTYs-720x340.png",alt:""})],-1)),i("p",null,[t[1]||(t[1]=s("本簡要指南介紹了在類 Unix 操作系統中如何在不使用功能鍵的情況下切換 TTY。在進一步討論之前，我們將瞭解 TTY 是什麼。正如在 AskUbuntu 論壇的一個",-1)),e(n,{href:"https://askubuntu.com/questions/481906/what-does-tty-stand-for"},{default:o(()=>[...t[0]||(t[0]=[s("答案",-1)])]),_:1}),t[2]||(t[2]=s("中所提到的，",-1)),t[3]||(t[3]=i("strong",null,"TTY",-1)),t[4]||(t[4]=s("這個詞來自 ",-1)),t[5]||(t[5]=i("strong",null,"T",-1)),t[6]||(t[6]=s("ele",-1)),t[7]||(t[7]=i("strong",null,"TY",-1)),t[8]||(t[8]=s("pewriter（電傳打字機）。在 Unix 的早期，連接到計算機的用户終端就是機電的電傳機或電傳打字機（簡稱 tty）。從那時起，TTY 這個名稱繼續用於純文本控制台。如今，所有文本控制台都代表虛擬控制台，而不是物理控制台。TTY 命令打印連接到標準輸入的終端的文件名。",-1))]),t[26]||(t[26]=u(`<h3 id="在-linux-中切換-tty" tabindex="-1">在 Linux 中切換 TTY <a class="header-anchor" href="#在-linux-中切換-tty" aria-label="Permalink to “在 Linux 中切換 TTY”">​</a></h3><p>默認情況下，Linux 中有 7 個 tty。它們被稱為 tty1、tty2……tty7。1 到 6 的 tty 只是命令列。第 7 個 tty 是 GUI（你的 X 桌面會話）。你可以使用 <code>CTRL+ALT+Fn</code> 鍵在不同的 TTY 之間切換。例如，要切換到 tty1，我們按下 <code>CTRL+ALT+F1</code>。這就是 tty1 在 Ubuntu 18.04 LTS 服務器中的樣子。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/tty1.png" alt=""></p><p>如果你的系統沒有 X 會話， 只需要按下 <code>Alt+Fn</code> 鍵，不需要按下 <code>CTRL</code>。</p><p>在某些 Linux 版本中（例如，從 Ubuntu 17.10 開始），登錄屏開始使用 1 號虛擬控制台。因此，你需要按 <code>CTRL+ALT+F3</code> 到 <code>CTRL+ALT+F6</code> 來訪問虛擬控制台。要返回桌面環境，請在 Ubuntu 17.10 及更高版本上按下 <code>CTRL+ALT+F2</code> 或 <code>CTRL+ALT+F7</code>。</p><p>目前為止我們看到我們可以使用 <code>CTRL+ALT+Fn</code>（<code>F1</code> - <code>F7</code>）在 TTY 之間輕鬆切換。但是，如果出於任何原因你不想使用功能鍵，那麼在 Linux 中有一個名為 <code>chvt</code> 的簡單命令。</p><p><code>chvt N</code> 命令讓你切換到前台終端 N，這與按 <code>CTRL+ALT+Fn</code> 相同。如果它不存在，則創建相應的屏幕。</p><p>讓我們試試顯示當前的 tty：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tty</span></span></code></pre></div><p>我的 Ubuntu 18.04 LTS 服務器的示例輸出。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/08/tty-command-output.png" alt=""></p><p>現在讓我們切換到 tty2。為此，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chvt 2</span></span></code></pre></div><p>記住你需要在 <code>chvt</code> 命令一同使用 <code>sudo</code>。</p><p>現在，使用命令檢查當前的 tty：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tty</span></span></code></pre></div><p>你會看到 tty 現在已經改變了。</p><p>同樣，你可以使用 <code>sudo chvt 3</code> 切換到 tty3，使用 <code>sudo chvt 4</code> 切換到 tty4 等等。</p><p>當任何一個功能鍵不起作用時，<code>chvt</code> 命令會很有用。</p><p>要查看活動虛擬控制台的總數，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fgconsole</span></span>
<span class="line"><span>2</span></span></code></pre></div><p>如你所見，我的系統中有兩個活動的虛擬終端。</p><p>你可以使用以下命令查看下一個未分配的虛擬終端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fgconsole --next-available</span></span>
<span class="line"><span>3</span></span></code></pre></div><p>如果虛擬控制台不是前台控制台，並且它沒有打開任何進程來讀取或寫入，並且未在其屏幕上選擇任何文本，則它是未使用的。</p><p>要移除未使用的虛擬終端，只需鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ deallocvt</span></span></code></pre></div><p>上面的命令為所有未使用的虛擬控制台釋放內核內存和數據結構。簡單地説，此命令將釋放連接到未使用的虛擬控制台的所有資源。</p><p>有關更多詳細信息，請參閲相應命令的手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man tty</span></span>
<span class="line"><span>$ man chvt</span></span>
<span class="line"><span>$ man fgconsole</span></span>
<span class="line"><span>$ man deallocvt</span></span></code></pre></div><p>就是這些了。希望這很有用。還有更多的好東西。敬請關注！</p><p>乾杯!</p><hr>`,33)),i("p",null,[t[10]||(t[10]=s("via: ",-1)),e(n,{href:"https://www.ostechnix.com/how-to-switch-between-ttys-without-using-function-keys-in-linux/"},{default:o(()=>[...t[9]||(t[9]=[s("https://www.ostechnix.com/how-to-switch-between-ttys-without-using-function-keys-in-linux/",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=s("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:o(()=>[...t[11]||(t[11]=[s("SK",-1)])]),_:1}),t[16]||(t[16]=s(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[12]||(t[12]=[s("lujun9972",-1)])]),_:1}),t[17]||(t[17]=s(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:o(()=>[...t[13]||(t[13]=[s("geekpi",-1)])]),_:1}),t[18]||(t[18]=s(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[14]||(t[14]=[s("wxy",-1)])]),_:1})]),i("p",null,[t[21]||(t[21]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[19]||(t[19]=[s("LCTT",-1)])]),_:1}),t[22]||(t[22]=s(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:o(()=>[...t[20]||(t[20]=[s("Linux中國",-1)])]),_:1}),t[23]||(t[23]=s(" 榮譽推出",-1))])])}const w=a(r,[["render",h]]);export{x as __pageData,w as default};
